import java.io.*;

public class P1152D_v3 {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        final int MODULO = 1000000007;
        int n = 0;
        int c = dis.read();
        while (c <= 32) c = dis.read();
        while (c > 32) {
            n = n * 10 + (c - '0');
            c = dis.read();
        }
        int m = 2 * n;
        int[][] f = new int[m + 1][m + 2];
        f[0][0] = 1;
        int ans = 0;
        for (int i = 1; i <= m; ++i) {
            f[i][0] = f[i - 1][1];
            for (int j = 1; j <= m; ++j) {
                f[i][j] = (f[i - 1][j - 1] + f[i - 1][j + 1]) % MODULO;
            }
            if (i % 2 == 1) {
                for (int j = 1; i + j <= m; j += 2)
                    ans = (ans + f[i][j]) % MODULO;
            }
        }
        writer.println(ans);
        writer.flush();
        writer.close();
        dis.close();
    }
}
